function p(t,c,o){return t+(c-t)*o}function x(t,c,o,s,n){const e=n*n,r=e*n,f=-r+2*e-n,h=3*r-5*e+2,u=-3*r+4*e+n,g=r-e;return{x:(f*t.x+h*c.x+u*o.x+g*s.x)/2,y:(f*t.y+h*c.y+u*o.y+g*s.y)/2,p:(f*t.p+h*c.p+u*o.p+g*s.p)/2}}function y(t,c=6){if(t.length<3)return t.map(n=>({...n}));const o=[t[0],...t.map(n=>({...n})),t[t.length-1]],s=[];for(let n=0;n<t.length-1;n++){const e=o[n],r=o[n+1],f=o[n+2],h=o[n+3];for(let u=0;u<c;u++){const g=u/c,i=x(e,r,f,h,g);i.p=p(r.p,f.p,g),s.push(i)}}return s.push({...t[t.length-1]}),s}self.onmessage=t=>{const{id:c,gen:o,samples:s}=t.data,n=y(s),e={id:c,gen:o,points:n};self.postMessage(e)};
